//! 23-bit noise LFSR (cycle-accurate).
//!
//! The SID noise waveform is generated by a 23-bit Fibonacci shift register
//! that is clocked from **bit 19 of the oscillator accumulator** (one shift per
//! rising edge of that bit). The edge is detected at chip rate directly by
//! [`crate::oscillator::Oscillator`]; this type only holds the register and
//! produces its tapped output (see `SID_ANALOG_SPEC.md` §4).

/// 23-bit linear-feedback shift register.
#[derive(Clone, Copy)]
pub struct Noise {
    /// The shift register (23 significant bits, `0..=0x7FFFFF`).
    pub sr: u32,
}

impl Noise {
    /// Power-on / reset seed.
    ///
    /// The real register seeds to `0x7FFFF8` after the TEST bit is cleared.
    pub const fn new() -> Self {
        Self { sr: 0x7F_FFF8 }
    }

    /// Advance the register by one step (called on each rising edge of
    /// accumulator bit 19).
    ///
    /// Feedback: `bit0 = sr[22] XOR sr[17]`.
    #[inline(always)]
    pub fn clock(&mut self) {
        let bit0 = ((self.sr >> 22) ^ (self.sr >> 17)) & 1;
        self.sr = ((self.sr << 1) | bit0) & 0x7F_FFFF;
    }

    /// Tapped 12-bit output word.
    ///
    /// The SID reads eight fixed, non-contiguous taps and places them in the
    /// upper bits of the 12-bit waveform word. This wiring is fixed hardware
    /// (not measured data), so it is reproduced exactly.
    #[inline(always)]
    pub fn output(&self) -> u32 {
        let sr = self.sr;
        ((sr & 0x40_0000) >> 11)
            | ((sr & 0x10_0000) >> 10)
            | ((sr & 0x01_0000) >> 7)
            | ((sr & 0x00_2000) >> 5)
            | ((sr & 0x00_0800) >> 4)
            | ((sr & 0x00_0080) >> 1)
            | ((sr & 0x00_0010) << 1)
            | ((sr & 0x00_0004) << 2)
    }

    /// TEST bit set: the register is cleared (bits fade toward zero on the real
    /// chip; modelled as an immediate clear).
    #[inline(always)]
    pub fn on_test_set(&mut self) {
        self.sr = 0;
    }

    /// TEST bit cleared: the register is reseeded.
    #[inline(always)]
    pub fn on_test_clear(&mut self) {
        self.sr = 0x7F_FFF8;
    }
}
